//! A log written through the writer handle on a legacy state root (one with no `state-format`
//! marker) keeps exactly the bytes today's readers expect.
//!
//! The fixture `fixtures/legacy_root_frames.txt` lists the log one frame per line: the hex of
//! each record frame, or `lineage` for an identity frame. Identity frames carry a random id
//! minted when the log is created, so they are checked for their place and their id, not their
//! bytes. The fixture was printed by the build at `86bf6289`, before version 4 frames existed,
//! and must not be regenerated by a later one: a later build that wrote different bytes would
//! only pin its own change. `BROCA_PRINT_LEGACY_FRAMES=1` prints what this build writes, for
//! comparing by hand.

use broca_core::{FileWalStore, WalHandle};
use broca_protocol::{BindIdentity, StepId};
use broca_wal::framing::{decode_next, DecodeStep, LINEAGE_FRAME_LEN};
use broca_wal::WalRecord;

const FIXTURE: &str = include_str!("../fixtures/legacy_root_frames.txt");

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

#[tokio::test]
async fn a_legacy_root_writes_the_pinned_frames() {
    let state_root = broca_test_support::scratch_root()
        .join(format!("broca-legacy-frame-pin-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&state_root);
    std::fs::create_dir_all(&state_root).unwrap();
    let store = FileWalStore::new(state_root.join("wal"));
    let session = BindIdentity::new("/legacy-pin", "runner", "pinned");
    let wal = store.open_with_class(&session, None, None).unwrap();
    let handle = WalHandle::spawn(wal, 7).unwrap();
    // An ordinary record (a version 1 frame), a record that needs a feature (a version 3
    // frame), and another ordinary one.
    for record in [
        WalRecord::TurnFinished { step_id: StepId(1) },
        WalRecord::InputTokenCapFrozen { limit: 4096 },
        WalRecord::TurnFinished { step_id: StepId(2) },
    ] {
        handle.record(record).into_result().unwrap();
    }
    handle.shutdown().await.unwrap();

    let bytes = std::fs::read(store.wal_path(&session)).unwrap();
    let mut lines = Vec::new();
    let mut lineage = None;
    let mut offset = 0;
    while offset < bytes.len() {
        match decode_next(&bytes[offset..]) {
            DecodeStep::Lineage {
                lineage_id,
                consumed,
            } => {
                assert_eq!(consumed, LINEAGE_FRAME_LEN);
                assert_eq!(
                    *lineage.get_or_insert(lineage_id),
                    lineage_id,
                    "one log, one identity"
                );
                lines.push("lineage".to_owned());
                offset += consumed;
            }
            DecodeStep::Record { consumed, .. } => {
                lines.push(hex(&bytes[offset..offset + consumed]));
                offset += consumed;
            }
            _ => panic!("the log does not decode at offset {offset}"),
        }
    }
    let _ = std::fs::remove_dir_all(&state_root);
    let written = lines.join("\n") + "\n";
    if std::env::var_os("BROCA_PRINT_LEGACY_FRAMES").is_some() {
        println!("{written}");
    }
    assert_eq!(written, FIXTURE);
}
